<?php defined('ABSPATH')||exit;$id=get_the_ID();$product=wc_get_product($id);$meta=fn($k)=>get_post_meta($id,$k,true);$decode=fn($k)=>json_decode((string)$meta($k),true)?:[];$model=$meta('_tgs_model3d_url');$thumb=$meta('_tgs_thumbnail_url');$gallery=$decode('_tgs_gallery');$items=$decode('_tgs_items');$plans=$decode('_tgs_installments');$power=$decode('_tgs_power');$games=$decode('_tgs_games');$compat=$decode('_tgs_compatibility');get_header();?><main class="tgs-landing"><section class="tgs-hero"><div class="tgs-viewer"><?php if($model):?><model-viewer src="<?php echo esc_url($model);?>" camera-controls auto-rotate shadow-intensity="1"></model-viewer><?php elseif($thumb):?><img src="<?php echo esc_url($thumb);?>" alt="<?php echo esc_attr(get_the_title());?>"><?php endif;?></div><div class="tgs-summary"><span class="tgs-kicker">THE GAMER SHOP</span><h1><?php echo esc_html(get_the_title());?></h1><div class="tgs-price"><small>Transferencia</small><strong><?php echo wp_kses_post(wc_price(((int)$meta('_tgs_price_transfer_cents'))/100));?></strong><span>Efectivo <?php echo wp_kses_post(wc_price(((int)$meta('_tgs_price_cash_cents'))/100));?></span></div><?php woocommerce_template_single_add_to_cart();?></div></section><?php if($gallery):?><section><h2>Galería</h2><div class="tgs-gallery"><?php foreach($gallery as $url):?><img src="<?php echo esc_url($url);?>" alt="Imagen del equipo" loading="lazy"><?php endforeach;?></div></section><?php endif;?><section class="tgs-grid"><article><h2>Componentes</h2><?php foreach($items as $item):?><div class="tgs-item"><?php if(!empty($item['imageUrl'])):?><img src="<?php echo esc_url($item['imageUrl']);?>" alt=""><?php endif;?><span><?php echo esc_html($item['name']??'');?></span></div><?php endforeach;?></article><article><h2>Financiación</h2><?php foreach($plans as $plan):?><p><?php echo esc_html(($plan['installments']??'').' cuotas · total '.wc_price(((int)($plan['totalCents']??0))/100));?></p><?php endforeach;?><h2>Potencia</h2><p><?php echo esc_html(($power['watts']??'—').' W · fuente '.($power['psu']??'—').' W');?><br><small><?php echo esc_html($power['note']??'');?></small></p></article></section><section><h2>Descripción</h2><?php echo wp_kses_post($meta('_tgs_description_html'));?></section><section class="tgs-grid"><article><h2>Juegos</h2><?php foreach($games as $game):?><p><strong><?php echo esc_html($game['name']??'');?></strong> · <?php echo esc_html($game['tier']??'');?></p><?php endforeach;?></article><article><h2>Compatibilidad</h2><ul><?php foreach($compat as $line):?><li><?php echo esc_html($line);?></li><?php endforeach;?></ul></article></section><div class="tgs-sticky" aria-hidden="true"><span><?php echo esc_html(get_the_title());?></span><strong><?php echo wp_kses_post($product->get_price_html());?></strong><a href="<?php echo esc_url($product->add_to_cart_url());?>" class="button">Agregar al carrito</a></div></main><?php get_footer();
